mapper.select:
SELECT id
FROM basecamp
WHERE status IN ('RECRUITING', 'CLOSED')
  AND start_date <= #{dueStartDate}
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

SELECT id
FROM basecamp
WHERE status = 'CONFIRMED'
  AND end_date < #{today}
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE basecamp
SET status = 'COMPLETED',
    completed_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'CONFIRMED'
  AND end_date < #{today}

UPDATE basecamp_application
SET status = 'EXPIRED',
    updated_at = #{now}
WHERE basecamp_id = #{basecampId}
  AND status = 'PENDING'
